209	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
210	    @Override
211	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
212	        Owner owner = this.clinicService.findOwnerById(ownerId);
213	        if (owner == null) {
214	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
215	        }
216	        HttpHeaders headers = new HttpHeaders();
217	        Pet pet = petMapper.toPet(petFieldsDto);
218	        owner.setId(ownerId);
219	        pet.setOwner(owner);
220	        pet.getType().setName(null);
221	        this.clinicService.savePet(pet);
222	        PetDto petDto = petMapper.toPetDto(pet);
223	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
224	            .buildAndExpand(pet.getId()).toUri());
225	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
226	    }
